  "Alīda": {
   "sources": [
    "https://github.com/nimda5/baltic-widgets/blob/codex/namedays-round4/research/namedays/round144-notes.json"
   ],
   "keep": true,
   "text": {
    "lv": [
     "Alīda varētu būt saīsinājums no tādiem vārdiem kā Adelheide. Vārdu Adelheide parasti skaidro ar ģermāņu adal + heit — «cēls + būtība». Tas ir pieņēmums: dokumentētu šī vārda cilmes skaidrojumu neesam atraduši."
    ],
    "ru": [
     "Alīda, вероятно, сокращение таких имён, как Adelheide. Имя Adelheide обычно объясняют через германское adal + heit — «благородный + сущность». Это предположение: документированного объяснения происхождения этого имени мы не нашли."
    ],
    "en": [
     "Alīda is probably a short form of names such as Adelheid. Adelheide is usually explained from Germanic adal + heit, “noble + kind”. This is a hypothesis: we have not found a documented explanation of this name’s origin."
    ],
    "lt": [
     "Alīda greičiausiai yra tokių vardų kaip Adelheide trumpinys. Vardas Adelheide paprastai aiškinamas germanų adal + heit („kilnus + prigimtis“). Tai prielaida: dokumentuoto šio vardo kilmės paaiškinimo neradome."
    ],
    "et": [
     "Alīda on tõenäoliselt selliste nimede nagu Adelheid lühend. Nime Adelheide seletatakse tavaliselt germaani sõnaga adal + heit ‘õilis + olemus’. See on oletus: dokumenteeritud seletust selle nime päritolule me ei leidnud."
    ]
   }
  },
